/**
 * Tech Debt Tracker — tool-local actions.
 *
 * Category: Risk & Governance (squad S5, Wave 2 — CRUD-backed tools)
 * Tool:     Debt inventory with interest-rate forecasting
 *
 * Agent surface: tool.tech_debt.*
 * Backing CRUD : workspace.tech_debt.* (auto-generated by defineCrudActions
 *                in src/lib/actions/workspace/index.ts).
 *
 * ─── CRUD-BACKED tool pattern (vs the calculator pattern) ────────────
 * Generic create / list / update / delete already exist via the
 * auto-generated workspace.tech_debt.* surface, so this file only adds
 * VERBS THE AGENT WANTS TO SPEAK in tech-debt's domain vocabulary:
 *
 *   1. compute_priority — pure, no persistence. Given impact + effort
 *      (and optional interestRate), return a priority score and a
 *      rank tier so the agent can plan without a workspace mutation.
 *   2. list_state       — read all items + summary stats (byArea,
 *      totals, open/resolved counts), sorted by priority. Saves the
 *      agent a follow-up reduce.
 *   3. mark_resolved    — convenience over workspace.tech_debt.update
 *      for the single most-mutated field's transition: setting
 *      resolvedAt to "now" (or a supplied timestamp).
 *   4. add_tag          — idempotent append to tags[]. Avoids the
 *      naive-patch overwrite bug a generic update would cause.
 *   5. set_area         — convenience for setting the area field, the
 *      grouping dimension behind the hotspot view.
 *
 * `add_tag` and `set_area` are additive operations on a specific row;
 * they read the current row first, mutate the relevant slot, then upsert.
 * Marked `requiresConfirmation: false` because they don't destroy data
 * and the natural agent phrasing ("tag the auth-rewrite debt with
 * 'urgent'") would be unbearable to confirm individually.
 *
 * `mark_resolved` is `requiresConfirmation: true` because it represents
 * the lifecycle transition the agent should not perform on a whim. The
 * transition IS reversible via a workspace.tech_debt.update patch that
 * clears resolvedAt, but the confirmation prompt matches user
 * expectations around "you're closing this item".
 *
 * ─── PRIORITY FORMULA ───────────────────────────────────────────────
 * The tool client (tech-debt-client.tsx:69-72) uses:
 *     priorityScore = impact * 4 - effort + (interestRate * ageDays) * 0.5
 *
 * This depends on `ageDays(item)` — the time since `raisedAt`. The
 * compute_priority action takes only {impact, effort, interestRate?}
 * with NO raisedAt (the agent shouldn't have to time-travel just to
 * sanity-check a number), so we use the spec-supplied age-independent
 * fallback that still rewards high-impact / low-effort / high-interest:
 *
 *     priority = (impact / max(0.5, effort)) * (1 + (interestRate ?? 0))
 *
 * The list_state action, by contrast, has each item's raisedAt
 * available, so it uses the SAME formula the tool client renders on
 * screen — so an agent listing items sees the same ordering the user
 * sees in the UI. The two surfaces are intentionally consistent with
 * what they show, even though they use different formulas under the
 * hood (compute_priority for planning; list_state for review).
 *
 * ─── ID NAMING ──────────────────────────────────────────────────────
 * Namespace is `tool.tech_debt` (snake_case to match the auto-generated
 * `workspace.tech_debt` CRUD surface — the tool slug in the URL is
 * "tech-debt", but action ids use snake_case for the
 * underscore-separated entity name).
 *
 * ─── ENTITY KIND ────────────────────────────────────────────────────
 * Server-side entity kind for tech-debt is `workspace:techDebt`
 * (camelCase, derived via kindFromToolId), matching the BROWSER sync
 * engine's collection registration (see workspace-store.ts:1320). Both
 * sides agree on the camelCase kind, so MCP-written tech-debt items
 * round-trip into the browser store on next page load.
 * ─────────────────────────────────────────────────────────────────────
 */

import { z } from "zod";
import { registry } from "../registry";
import { useWorkspaceStore } from "@/lib/stores/workspace-store";
import { serverListEntities, serverGetEntity, serverUpsertEntity } from "../server-store";
import type { TechDebtItem } from "@/lib/stores/workspace-types";

/** Server-side entity kind. Matches kindFromToolId("workspace.tech_debt")
 *  used by the auto-generated CRUD in src/lib/actions/workspace/index.ts,
 *  and the browser sync engine's "workspace:techDebt" collection — both
 *  camelCase, so server and browser reads/writes line up. */
const KIND_TECH_DEBT = "workspace:techDebt";

const ws = () => useWorkspaceStore.getState();

function nowIso(): string {
  return new Date().toISOString();
}

/** Floor effort at 0.5 — division-by-zero defuse mirroring the
 *  pattern wsjf uses for jobSize. The TechDebtItem type pins effort
 *  to 1..5 in practice, but the compute_priority action accepts free
 *  numbers so an agent can experiment with fractional values. */
function safeDivPriority(impact: number, effort: number, interestRate: number | undefined): number {
  const e = Math.max(0.5, effort);
  return (impact / e) * (1 + (interestRate ?? 0));
}

/** Tier thresholds calibrated for the spec formula. With impact ∈ [1,5]
 *  and effort ∈ [1,5] and interestRate typically 0..3, the base ratio
 *  impact/effort lands in [0.2, 5]. The (1+rate) multiplier scales up
 *  to ~20 at the high end. We bucket:
 *    >= 3.0   → must_fix    (high impact OR low effort + meaningful interest)
 *    >= 1.0   → should_fix  (parity zone — impact balances effort)
 *    <  1.0   → defer       (effort outweighs impact, low interest)
 */
function rankTier(priority: number): "must_fix" | "should_fix" | "defer" {
  if (priority >= 3.0) return "must_fix";
  if (priority >= 1.0) return "should_fix";
  return "defer";
}

/** Age-aware priority matching the tool client. Used by list_state
 *  so the agent sees the same ordering as the on-screen ranking. */
function clientPriorityScore(item: TechDebtItem): number {
  const interest = (item.interestRate ?? 0) * localAgeDays(item.raisedAt);
  return item.impact * 4 - item.effort + interest * 0.5;
}

/** Whole local calendar days since raisedAt, as the tool client counts them
 *  (a YYYY-MM-DD date is a local day, not UTC midnight); 0 if unparseable
 *  or in the future. */
function localAgeDays(raisedAt: string | undefined): number {
  const raw = raisedAt ?? "";
  const raised = new Date(/^\d{4}-\d{2}-\d{2}$/.test(raw) ? `${raw}T00:00:00` : raw);
  if (!Number.isFinite(raised.getTime())) return 0;
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
  const day = new Date(raised.getFullYear(), raised.getMonth(), raised.getDate()).getTime();
  return Math.max(0, Math.round((today - day) / 86_400_000));
}

// ──────── tool.tech_debt.compute_priority ────────
// Pure: priority + tier for a hypothetical debt item. No persistence.
// Used during planning ("if I log this as impact 4, effort 2, where
// would it rank?") without forcing the agent to actually create the
// row. Pure, so no mcpHandler needed — runs identically on every host.
registry.register({
  id: "tool.tech_debt.compute_priority",
  toolId: "tool.tech_debt",
  name: "compute_priority",
  category: "read",
  description:
    "Compute a priority score and rank tier (must_fix | should_fix | defer) for a hypothetical tech-debt item. Pure — no persistence. Formula: (impact / max(0.5, effort)) * (1 + (interestRate ?? 0)). Note: list_state uses an age-aware formula matching the in-app ranking; this action is for age-independent planning.",
  paramsSchema: z.object({
    impact: z.number().min(0).describe("Estimated impact, typically 1-5"),
    effort: z.number().min(0).describe("Estimated effort, typically 1-5 (floored at 0.5)"),
    interestRate: z
      .number()
      .min(0)
      .optional()
      .describe("Optional interest per sprint (velocity units bleed). Defaults to 0."),
  }),
  handler: async (params) => {
    const priority = safeDivPriority(params.impact, params.effort, params.interestRate);
    return {
      priority,
      rank_tier: rankTier(priority),
      formula: "(impact / max(0.5, effort)) * (1 + (interestRate ?? 0))",
    };
  },
});

// ──────── tool.tech_debt.list_state ────────
// Snapshot + summary stats, sorted by the on-screen priority formula
// so the agent sees the same ranking the user sees.
registry.register({
  id: "tool.tech_debt.list_state",
  toolId: "tool.tech_debt",
  name: "list_state",
  category: "read",
  description:
    "List all tech-debt items in the workspace: open items by priority (descending), then resolved ones. Returns {totalImpact, totalEffort, openCount, resolvedCount, byArea: Record<area, count>, items: sorted}. Items without an area roll up under '__unassigned'.",
  paramsSchema: z.object({}),
  handler: async () => {
    return summarize(ws().techDebt ?? []);
  },
  mcpHandler: async (_params, ctx) => {
    const items = await serverListEntities<TechDebtItem>(ctx.userId, KIND_TECH_DEBT);
    return summarize(items);
  },
});

/** Build the response shape. Shared between browser and MCP handlers
 *  so the two paths can't drift. */
function summarize(items: TechDebtItem[]) {
  const byArea: Record<string, number> = {};
  let totalImpact = 0;
  let totalEffort = 0;
  let openCount = 0;
  let resolvedCount = 0;
  for (const it of items) {
    totalImpact += it.impact;
    totalEffort += it.effort;
    if (it.resolvedAt) resolvedCount += 1;
    else openCount += 1;
    const area = it.area && it.area.length > 0 ? it.area : "__unassigned";
    byArea[area] = (byArea[area] ?? 0) + 1;
  }
  // Sort like the tool's on-screen `ranked` view: open items by
  // client-priority descending, then resolved ones.
  const sorted = items
    .slice()
    .sort(
      (a, b) =>
        Number(Boolean(a.resolvedAt)) - Number(Boolean(b.resolvedAt)) ||
        clientPriorityScore(b) - clientPriorityScore(a)
    );
  return {
    totalImpact,
    totalEffort,
    openCount,
    resolvedCount,
    byArea,
    items: sorted,
  };
}

// ──────── tool.tech_debt.mark_resolved ────────
// Convenience over workspace.tech_debt.update for the lifecycle-defining
// field transition. Default resolvedAt is the call time, but the agent
// can supply a past timestamp (e.g. "we actually fixed this last
// sprint"). Returns {updated: boolean} for missing-id detection without
// a throw.
//
// requiresConfirmation:true — see file header. This is the "you're
// closing this item" transition; the action IS reversible via a clear
// patch but the prompt matches user expectations.
registry.register({
  id: "tool.tech_debt.mark_resolved",
  toolId: "tool.tech_debt",
  name: "mark_resolved",
  category: "write",
  requiresConfirmation: true,
  description:
    "Mark an existing tech-debt item resolved by setting resolvedAt. Defaults to the current ISO timestamp; pass a custom resolvedAt to back-date. Returns {updated: false} when the id is unknown. Reversible via a workspace.tech_debt.update patch that clears resolvedAt.",
  paramsSchema: z.object({
    id: z.string(),
    resolvedAt: z
      .string()
      .datetime({ offset: true })
      .optional()
      .describe("Optional ISO-8601 timestamp; defaults to the current time"),
  }),
  handler: async (params) => {
    const items = ws().techDebt ?? [];
    const current = items.find((d) => d.id === params.id);
    if (!current) return { updated: false };
    ws().upsertTechDebt({ ...current, resolvedAt: params.resolvedAt ?? nowIso() });
    return { updated: true };
  },
  mcpHandler: async (params, ctx) => {
    const current = await serverGetEntity<TechDebtItem>(ctx.userId, KIND_TECH_DEBT, params.id);
    if (!current) return { updated: false };
    await serverUpsertEntity<TechDebtItem>(ctx.userId, KIND_TECH_DEBT, {
      ...current,
      resolvedAt: params.resolvedAt ?? nowIso(),
    });
    return { updated: true };
  },
});

// ──────── tool.tech_debt.add_tag ────────
// Idempotent append to tags[]. Read-modify-write through the store /
// server so a concurrent agent call that already added the same tag
// won't produce duplicates. Returns {added: boolean} — false when the
// tag was already present OR the item is missing.
registry.register({
  id: "tool.tech_debt.add_tag",
  toolId: "tool.tech_debt",
  name: "add_tag",
  category: "write",
  requiresConfirmation: false,
  description:
    "Append a tag to an existing tech-debt item's tags[]. Idempotent — skips if the tag is already present. Returns {added: false} when the id is unknown OR the tag was already there.",
  paramsSchema: z.object({
    id: z.string(),
    tag: z.string().min(1).max(80),
  }),
  handler: async (params) => {
    const items = ws().techDebt ?? [];
    const current = items.find((d) => d.id === params.id);
    if (!current) return { added: false };
    const existing = current.tags ?? [];
    if (existing.includes(params.tag)) return { added: false };
    ws().upsertTechDebt({ ...current, tags: [...existing, params.tag] });
    return { added: true };
  },
  mcpHandler: async (params, ctx) => {
    const current = await serverGetEntity<TechDebtItem>(ctx.userId, KIND_TECH_DEBT, params.id);
    if (!current) return { added: false };
    const existing = current.tags ?? [];
    if (existing.includes(params.tag)) return { added: false };
    await serverUpsertEntity<TechDebtItem>(ctx.userId, KIND_TECH_DEBT, {
      ...current,
      tags: [...existing, params.tag],
    });
    return { added: true };
  },
});

// ──────── tool.tech_debt.set_area ────────
// Convenience for the grouping field behind the hotspot view.
// Overwrites whatever area was previously set (this is a categorisation
// move, not an additive list — the previous area is no longer correct
// once moved). Returns {updated: boolean}.
registry.register({
  id: "tool.tech_debt.set_area",
  toolId: "tool.tech_debt",
  name: "set_area",
  category: "write",
  requiresConfirmation: false,
  description:
    "Set the area field on an existing tech-debt item. Overwrites the previous value (this is a categorisation move, not an append). Returns {updated: false} when the id is unknown.",
  paramsSchema: z.object({
    id: z.string(),
    area: z.string().min(1).max(120),
  }),
  handler: async (params) => {
    const items = ws().techDebt ?? [];
    const current = items.find((d) => d.id === params.id);
    if (!current) return { updated: false };
    ws().upsertTechDebt({ ...current, area: params.area });
    return { updated: true };
  },
  mcpHandler: async (params, ctx) => {
    const current = await serverGetEntity<TechDebtItem>(ctx.userId, KIND_TECH_DEBT, params.id);
    if (!current) return { updated: false };
    await serverUpsertEntity<TechDebtItem>(ctx.userId, KIND_TECH_DEBT, {
      ...current,
      area: params.area,
    });
    return { updated: true };
  },
});
